// Formata os dois JSONs (cost-report + security-report) em um HTML de e-mail.
// Comentários em português conforme padrão do projeto setup-platform.
const costRaw = $input.all()[0].json.stdout;
const secRaw = $input.all()[1] ? $input.all()[1].json.stdout : '{}';

let cost, sec;
try { cost = JSON.parse(costRaw); } catch (e) { cost = {}; }
try { sec = JSON.parse(secRaw); } catch (e) { sec = {}; }

const fmtUsd = (v) => `US$ ${Number(v || 0).toFixed(2)}`;

const topServicesRows = (cost.cost?.topServices || [])
  .map(s => `<tr><td>${s.service}</td><td>${fmtUsd(s.cost)}</td></tr>`)
  .join('');

const openSgRows = (sec.openSecurityGroups || [])
  .map(s => `<li>${s.groupId} (${s.groupName}) porta ${s.fromPort}-${s.toPort}/${s.protocol} &lt;- ${s.cidr}</li>`)
  .join('') || '<li>nenhum encontrado</li>';

const idleEipRows = (cost.idleResources?.unassociatedElasticIps || [])
  .map(e => `<li>${e.publicIp}</li>`).join('') || '<li>nenhum</li>';

const html = `
<h2>Relatório Semanal AWS FinOps &amp; Segurança</h2>
<p>Gerado em: ${cost.generatedAt || new Date().toISOString()}</p>
<h3>Custos</h3>
<ul>
  <li>Últimos 7 dias: ${fmtUsd(cost.cost?.last7Days?.total)} (variação: ${cost.cost?.last7Days?.variationPct ?? 'N/A'}%)</li>
  <li>Últimos 30 dias: ${fmtUsd(cost.cost?.last30Days?.total)} (variação: ${cost.cost?.last30Days?.variationPct ?? 'N/A'}%)</li>
</ul>
<h4>Top serviços (30 dias)</h4>
<table border="1" cellpadding="6" cellspacing="0"><tr><th>Serviço</th><th>Custo</th></tr>${topServicesRows}</table>
<h4>Recursos ociosos — Elastic IPs não associados</h4>
<ul>${idleEipRows}</ul>
<h3>Segurança</h3>
<h4>Security Groups expostos (0.0.0.0/0) em portas sensíveis</h4>
<ul>${openSgRows}</ul>
<p>Usuários sem MFA: ${(sec.usersWithoutMfa || []).length} | Access keys antigas: ${(sec.oldAccessKeys || []).length} | Buckets S3 públicos: ${(sec.publicS3Buckets || []).length}</p>
<hr/>
<p style="font-size:12px;color:#888">Relatório gerado automaticamente pelo AWS Monitor / FinOps Agent (setup-platform). Somente leitura, nenhuma ação foi executada na conta.</p>
`;

const slackSummary = `*Relatório AWS FinOps (semanal)*\n` +
  `Custo 7d: ${fmtUsd(cost.cost?.last7Days?.total)} (${cost.cost?.last7Days?.variationPct ?? 'N/A'}%)\n` +
  `Custo 30d: ${fmtUsd(cost.cost?.last30Days?.total)} (${cost.cost?.last30Days?.variationPct ?? 'N/A'}%)\n` +
  `SGs expostos: ${(sec.openSecurityGroups || []).length} | Sem MFA: ${(sec.usersWithoutMfa || []).length} | Buckets públicos: ${(sec.publicS3Buckets || []).length}`;

return [{ json: { html, slackSummary } }];
